import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  // --- Edge case: empty policy ---
  it("empty item list → premium 5 G (only the processing fee)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [] }],
    });

    expect(result.results).toEqual([{ premium: 5 }]);
  });

  // --- Base premiums for main items (with first-insurance surcharge and fee) ---
  it("a single plain sword for a new customer → 100 G base + 10 G first insurance + 5 G fee = 115 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [{ type: "sword", material: "steel", enchantment: 3, cursed: false }],
        },
      ],
    });

    expect(result.results).toEqual([{ premium: 115 }]);
  });
  it("a single plain amulet for a new customer → 60 G base + 6 G first insurance + 5 G fee = 71 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [{ type: "amulet", material: "silver", enchantment: 2, cursed: false }],
        },
      ],
    });

    expect(result.results).toEqual([{ premium: 71 }]);
  });
  it("a single plain staff for a new customer → 80 G base + 8 G first insurance + 5 G fee = 93 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [{ type: "staff", material: "oak", enchantment: 1, cursed: false }],
        },
      ],
    });

    expect(result.results).toEqual([{ premium: 93 }]);
  });
  it.todo("a single plain potion for a new customer → 40 G base + 4 G first insurance + 5 G fee = 49 G");

  // --- Components and building blocks ---
  it.todo("2 runes → 50 G base premium");
  it.todo("3 runes → 60 G base premium (block of 3 alike components applies)");
  it.todo("4 runes → 100 G base premium (no block — block requires exactly 3)");
  it.todo("7 runes → 175 G base premium");
  it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types)");
  it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");

  // --- Item-level modifiers ---
  it.todo("a cursed sword → 50 % risk surcharge on its base premium (100 G → 150 G)");
  it.todo("a sword with enchantment 5 → 30 % high-enchantment surcharge applies (100 G → 130 G)");
  it.todo("a sword with enchantment 4 → no high-enchantment surcharge (100 G base)");
  it.todo("a cursed sword with enchantment 5 → both surcharges apply (100 G → 180 G)");

  // --- Modifier scope on multi-item policies ---
  it.todo("cursed sword + plain amulet → policy base 160 G, curse adds 50 G (50 % of the cursed item only) → 210 G before further modifiers and fee");

  // --- Policy-level modifiers ---
  it.todo("customer with exactly 2 years with MHPCO → 20 % loyalty discount applies");
  it.todo("customer with 1 year with MHPCO → no loyalty discount");
  it.todo("every quote carries the 10 % first insurance surcharge, regardless of customer history");
  it.todo("the second quote in a scenario receives the 15 % follow-up contract discount");

  // --- Rounding in MHPCO's favor ---
  it.todo("a premium calculation that yields 197.5 G → final premium 198 G (rounded up)");
  it.todo("a payout calculation that yields 350.5 G → final payout 350 G (rounded down)");

  // --- Integration examples ---
  it.todo("newcomer (0 years, no previous contract) with a cursed steel sword, enchantment 3 → premium 165 G");
  it.todo("3-year customer's second quote of a cursed steel sword, enchantment 7 → premium 160 G");

  // --- Claims: standard reimbursement ---
  it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G (damage minus 100 G deductible)");
  it.todo("damage to a rune (no enchantment, no material), damage 200 G → payout 100 G");

  // --- Claims: special clauses ---
  it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G (full reimbursement, then deductible)");
  it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % first, then deductible)");
  it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (the 50 % rule wins over dragon material)");
  it.todo("dragon-material sword with exactly enchantment 8, damage 1000 G → payout 400 G (high-enchantment clause applies, then deductible)");

  // --- Claims: deductible per damage event ---
  it.todo("a dragon attack damages a sword (500 G) and an amulet (300 G) → payout 600 G (deductible applies once per damaged item)");

  // --- Claims: insurance sum and cap ---
  it.todo("a policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
  it.todo("a policy covering two swords → insurance sum 2000 G, cap 4000 G");
  it.todo("a policy covering a sword and 3 runes → insurance sum 1750 G (block discount affects the premium only)");
  it.todo("a cursed sword (premium with modifiers 165 G) → cap 2000 G (premium modifiers do not raise the cap)");
  it.todo("sword insured (cap 2000 G), two successive claims of 1500 G each → first payout 1400 G with remainingCap 600 G, second payout 600 G with remainingCap 0 G");

  // --- Multiple items of the same type ---
  it.todo("two swords insured, a dragon attack damages both → each damage entry gets its own deductible");

  // --- Error cases (CLI exits non-zero, error on stderr) ---
  it.todo("quote includes an item with an unknown type (e.g. broomstick) → error, no results");
  it.todo("claim references an item not part of the policy (amulet damaged when only a sword is insured) → error");
  it.todo("claim references a damage entry with an unknown item type → error");
  it.todo("claim contains more damage entries of a type than the policy covers (two sword damages, one sword insured) → error");
  it.todo("claim contains a damage entry with amount: -200 → error");

  // --- CLI ---
  it.todo("the CLI reads a scenario from stdin and writes {results: [...]} to stdout in step order");
  it.todo("the CLI exits with a non-zero status code and writes an error description to stderr on an invalid scenario");
});

