export type Item = {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
};

export type QuoteStep = {
  op: "quote";
  items: Item[];
};

export type Scenario = {
  customer: { yearsWithMHPCO: number };
  steps: QuoteStep[];
};

export type ScenarioResult = {
  results: unknown[];
};

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE = 0.1;

/** Premiums round up — in the MHPCO's favour. Float noise is discarded first. */
const roundUpToWholeG = (amount: number): number => Math.ceil(Number(amount.toFixed(6)));

/** The item types the MHPCO will insure, and what each costs to cover. */
const BASE_PREMIUMS: Record<string, number | undefined> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

/** Premium for a single item of this type. `undefined` for a type the MHPCO does not insure — rejecting those is not yet specified by a test. */
const unitPremiumFor = (type: string): number | undefined => BASE_PREMIUMS[type];

/** Component types that form discounted blocks. */
const BLOCK_FORMING_COMPONENTS = new Set(["rune", "moonstone"]);
const COMPONENT_BLOCK_SIZE = 3;
const COMPONENT_BLOCK_PREMIUM = 60;

const formsComponentBlock = (type: string, count: number): boolean =>
  BLOCK_FORMING_COMPONENTS.has(type) && count === COMPONENT_BLOCK_SIZE;

const countByType = (items: Item[]): Map<string, number> => {
  const counts = new Map<string, number>();
  for (const item of items) {
    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
  }
  return counts;
};

/** Alike components form a discounted block; everything else is priced per unit. */
const basePremiumForGroup = (type: string, count: number): number => {
  if (formsComponentBlock(type, count)) return COMPONENT_BLOCK_PREMIUM;
  const unitPremium = unitPremiumFor(type);
  // An uninsurable type yields NaN, which propagates to the quote. Rejecting
  // unknown types with a real error is specified by a test we have not reached yet.
  return unitPremium === undefined ? NaN : count * unitPremium;
};

const policyBasePremium = (items: Item[]): number =>
  [...countByType(items)].reduce(
    (total, [type, count]) => total + basePremiumForGroup(type, count),
    0,
  );

const CURSE_SURCHARGE_RATE = 0.5;

/** Item-level surcharge rates stack additively on one item. */
const surchargeRateFor = (item: Item): number => (item.cursed ? CURSE_SURCHARGE_RATE : 0);

/**
 * Item-level surcharges apply to the affected item's own base premium, not to
 * the policy total. An uninsurable type yields NaN and propagates to the quote,
 * as in `basePremiumForGroup`.
 */
const itemSurchargeTotal = (items: Item[]): number =>
  items.reduce(
    (total, item) => total + (unitPremiumFor(item.type) ?? NaN) * surchargeRateFor(item),
    0,
  );

const quotePremium = (items: Item[]): number => {
  const policyBase = policyBasePremium(items) + itemSurchargeTotal(items);
  const withFirstInsurance = policyBase * (1 + FIRST_INSURANCE_SURCHARGE);
  const withProcessingFee = withFirstInsurance + PROCESSING_FEE;
  return roundUpToWholeG(withProcessingFee);
};

export const runScenario = (scenario: Scenario): ScenarioResult => {
  return { results: scenario.steps.map((step) => ({ premium: quotePremium(step.items) })) };
};

