type ModifierRule<Subject> = { applies: (subject: Subject) => boolean; rate: number };

/** Modifier rates stack additively — at both the item and the policy level. */
const sumApplicableRates = <Subject>(
  rules: ModifierRule<Subject>[],
  subject: Subject,
