    0,
  );

const LOYALTY_DISCOUNT_RATE = 0.2;
const LOYALTY_YEARS_THRESHOLD = 2;

/** Each policy-level modifier, and the rate it contributes. Discounts are negative. */
const POLICY_MODIFIER_RULES: { applies: (customer: Customer) => boolean; rate: number }[] = [
  {
    applies: (customer) => customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD,
    rate: -LOYALTY_DISCOUNT_RATE,
  },
  { applies: () => true, rate: FIRST_INSURANCE_SURCHARGE },
];

/**
 * Policy-level modifiers are percentages of the policy base premium and stack
 * additively, per the MHPCO's worked examples.
 */
const policyModifierRate = (customer: Customer): number =>
  sumApplicableRates(POLICY_MODIFIER_RULES, customer);

const quotePremium = (items: Item[], customer: Customer): number => {
  const policyBase = policyBasePremium(items) + itemSurchargeTotal(items);
  const withPolicyModifiers = policyBase * (1 + policyModifierRate(customer));
  const withProcessingFee = withPolicyModifiers + PROCESSING_FEE;
  return roundUpToWholeG(withProcessingFee);
};

export const runScenario = (scenario: Scenario): ScenarioResult => {
  return {
    results: scenario.steps.map((step) => ({
      premium: quotePremium(step.items, scenario.customer),
    })),
  };
};

