/** What each item type is insured for. */
const INSURANCE_VALUES: Record<string, number> = {
  sword: 1000,
  amulet: 600,
  staff: 800,
  potion: 400,
  rune: 250,
  moonstone: 250,
};

const DEDUCTIBLE_PER_DAMAGE = 100;
const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;

/** Payouts round down — in the MHPCO's favour. Float noise is discarded first. */
const roundDownToWholeG = (amount: number): number => Math.floor(Number(amount.toFixed(6)));

/** A policy created by a quote step, tracked across the claims made against it. */
type Policy = {
  items: Item[];
  remainingCap: number;
};

const openPolicy = (items: Item[]): Policy => {
  const insuranceSum = items.reduce((sum, item) => sum + (INSURANCE_VALUES[item.type] ?? NaN), 0);
  return { items, remainingCap: insuranceSum * CAP_MULTIPLE_OF_INSURANCE_SUM };
};

/** A deductible applies once per damaged item. */
const payoutForDamage = (damage: Damage): number =>
  Math.max(0, damage.amount - DEDUCTIBLE_PER_DAMAGE);

const settleClaim = (policy: Policy, damages: Damage[]): { payout: number; remainingCap: number } => {
  const desired = damages.reduce((total, damage) => total + payoutForDamage(damage), 0);
  const payout = roundDownToWholeG(Math.min(desired, policy.remainingCap));
  policy.remainingCap -= payout;
  return { payout, remainingCap: policy.remainingCap };
};

export const runScenario = (scenario: Scenario): ScenarioResult => {
  const policies = new Map<number, Policy>();

  const results = scenario.steps.map((step, index) => {
    if (step.op === "claim") {
      const policy = policies.get(step.policy)!;
      return settleClaim(policy, step.incident.damages);
    }

    policies.set(index, openPolicy(step.items));
    return {
      premium: quotePremium(step.items, {
        customer: scenario.customer,
        precedingContracts: policies.size - 1,
      }),
    };
  });

  return { results };
};

