  const uncappedPayout = damages.reduce(
    (total, damage) =>
      total + payoutForDamage(damage, damagedItem(policy, damage.itemType)),
    0,
  );
  const payout = roundDownToWholeG(Math.min(uncappedPayout, policy.remainingCap));
  const remainingCap = policy.remainingCap - payout;
  return { settlement: { payout, remainingCap }, policy: { ...policy, remainingCap } };
};

export const runScenario = (scenario: Scenario): ScenarioResult => {
  const policies = new Map<number, Policy>();

  const results = scenario.steps.map((step, index) => {
    if (step.op === "claim") {
      const { settlement, policy } = settleClaim(
        policies.get(step.policy)!,
        step.incident.damages,
      );
      policies.set(step.policy, policy);
      return settlement;
    }

    policies.set(index, openPolicy(step.items));
    return {
      premium: quotePremium(step.items, {
        customer: scenario.customer,
        precedingContracts: policies.size - 1,
      }),
